const visual = {
  prepare: function (input) {
    return [
      {kind:'text', payload:'两列同频同相正弦波及其合成波'},
      {kind:'text', payload:'x'},
      {kind:'text', payload:'y'},
      {kind:'text', payload:'2.5'},
      {kind:'text', payload:'1.5'},
      {kind:'text', payload:'4'},
      {kind:'text', payload:'合成振幅 4'},
      {kind:'text', payload:'y₁ = 2.5 sin t'},
      {kind:'text', payload:'y₂ = 1.5 sin t'},
      {kind:'text', payload:'y = y₁ + y₂ = 4 sin t'},
      {kind:'text', payload:'同频同相'}
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu || 760;
    var H = input.viewport.heightDu || 460;
    var x0 = W * 0.11;
    var x1 = W * 0.94;
    var y0 = H * 0.50;
    var yTop = H * 0.12;
    var yBottom = H * 0.82;
    var scale = Math.min((y0 - yTop) / 4, (yBottom - y0) / 4);
    var AXIS = '#3b4a5a';
    var BLUE = '#2f6fbf';
    var GREEN = '#1f9d6a';
    var ORANGE = '#d9552a';
    var paths = [];
    var pathNodes = [];
    function addPath(id, commands, stroke, width, extra) {
      paths.push({id:id, commands:commands});
      var node = {type:'path', pathId:id, stroke:stroke, strokeWidth:width || 1.5, fill:'none'};
      if (extra) { for (var k in extra) { node[k] = extra[k]; } }
      pathNodes.push(node);
    }
    var labels = [];
    function addLabel(text, x, y, size, fill, anchor, weight) {
      labels.push({type:'label', text:text, x:x, y:y, fontSize:size || 14, fill:fill || '#26354a', textAnchor:anchor || 'start', fontWeight:weight || 'normal'});
    }
    addPath('axisX', visualSdk.axis({x0:x0, y0:y0, x1:x1, y1:y0, ticks:8, tickLength:5}), AXIS, 1.4);
    addPath('axisY', visualSdk.axis({x0:x0, y0:yBottom, x1:x0, y1:yTop, ticks:8, tickLength:5}), AXIS, 1.4);
    addPath('h4', visualSdk.polyline([[x0-6, y0-4*scale],[x1+6, y0-4*scale]]), ORANGE, 0.9, {strokeDasharray:[5,4], opacity:0.55});
    addPath('h25', visualSdk.polyline([[x0-6, y0-2.5*scale],[x1+6, y0-2.5*scale]]), BLUE, 0.8, {strokeDasharray:[4,5], opacity:0.35});
    addPath('h15', visualSdk.polyline([[x0-6, y0-1.5*scale],[x1+6, y0-1.5*scale]]), GREEN, 0.8, {strokeDasharray:[4,5], opacity:0.35});
    var N = 320;
    function waveCommands(amplitude) {
      var pts = [];
      for (var i = 0; i <= N; i++) {
        var t = 4 * Math.PI * i / N;
        var x = x0 + (x1 - x0) * i / N;
        var y = y0 - amplitude * scale * Math.sin(t);
        pts.push([x, y]);
      }
      return visualSdk.polyline(pts);
    }
    addPath('wSum', waveCommands(4.0), ORANGE, 3.0);
    addPath('w1', waveCommands(2.5), BLUE, 2.0);
    addPath('w2', waveCommands(1.5), GREEN, 2.0);
    var xPeak = x0 + (x1 - x0) * 0.125;
    var yPeak = y0 - 4 * scale;
    addPath('ampArrow', visualSdk.arrow(xPeak, y0, xPeak, yPeak, {}), ORANGE, 1.2);
    addPath('tick25', visualSdk.polyline([[xPeak-5, y0-2.5*scale],[xPeak+5, y0-2.5*scale]]), BLUE, 1.2);
    addPath('tick15', visualSdk.polyline([[xPeak-5, y0-1.5*scale],[xPeak+5, y0-1.5*scale]]), GREEN, 1.2);
    addPath('tick4', visualSdk.polyline([[xPeak-5, yPeak],[xPeak+5, yPeak]]), ORANGE, 1.2);
    addPath('axisTick4', visualSdk.polyline([[x0-6, yPeak],[x0+6, yPeak]]), ORANGE, 1.0);
    addPath('axisTick25', visualSdk.polyline([[x0-6, y0-2.5*scale],[x0+6, y0-2.5*scale]]), BLUE, 1.0);
    addPath('axisTick15', visualSdk.polyline([[x0-6, y0-1.5*scale],[x0+6, y0-1.5*scale]]), GREEN, 1.0);
    var legendY1 = H - 38;
    var legendY2 = H - 16;
    addPath('legend1', visualSdk.polyline([[x0, legendY1],[x0+26, legendY1]]), BLUE, 2.5);
    addPath('legend2', visualSdk.polyline([[x0+180, legendY1],[x0+206, legendY1]]), GREEN, 2.5);
    addPath('legend3', visualSdk.polyline([[x0, legendY2],[x0+26, legendY2]]), ORANGE, 3.0);
    addLabel('两列同频同相正弦波及其合成波', W/2, 24, 16, '#1f2d3a', 'middle', 'bold');
    addLabel('x', x1+10, y0+16, 15, AXIS, 'start');
    addLabel('y', x0-18, yTop+4, 15, AXIS, 'start');
    addLabel('2.5', x0-10, y0-2.5*scale+5, 14, BLUE, 'end');
    addLabel('1.5', x0-10, y0-1.5*scale+5, 14, GREEN, 'end');
    addLabel('4', x0-10, yPeak+5, 14, ORANGE, 'end');
    addLabel('合成振幅 4', xPeak+8, yPeak-8, 14, ORANGE, 'start', 'bold');
    addLabel('y₁ = 2.5 sin t', x0+34, legendY1+5, 13, BLUE, 'start');
    addLabel('y₂ = 1.5 sin t', x0+214, legendY1+5, 13, GREEN, 'start');
    addLabel('y = y₁ + y₂ = 4 sin t', x0+34, legendY2+5, 13, ORANGE, 'start');
    addLabel('同频同相', x0+260, legendY2+5, 13, AXIS, 'start');
    return {schemaVersion:1, sceneId:'sine-sum-transcription', revision:input.revision, viewBox:{x:0, y:0, width:W, height:H}, paths:paths, root:{type:'group', children:pathNodes.concat(labels)}};
  }
};
